By definition of variance:
\begin{align*}
\mathbb{E}_{i} \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i - \nabla f(w) \right\|^2 \right] &= \mathbb{E}_{i} \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i \right\|^2 \right] - \|\nabla f(w)\|^2
\end{align*}
Rearranging yields the result.
\end{proof}

% ADDED: Lemma to bound the second moment of the stochastic gradient
\begin{lemma}[Second Moment Bound]
For any $w \in \mathbb{R}^d$, if the variance is bounded by $\sigma^2$, the second moment of the scaled coordinate gradient is bounded by:
\begin{align*}
\mathbb{E}_{i} \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i \right\|^2 \right] \leq \|\nabla f(w)\|^2 + \sigma^2
\end{align*}
\end{lemma}
\begin{proof}
Substitute the variance bound directly into the equality from Lemma 2:
\begin{align*}
\mathbb{E}_{i} \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i \right\|^2 \right] &= \|\nabla f(w)\|^2 + \mathbb{E}_{i} \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i - \nabla f(w) \right\|^2 \right] \\
&\leq \|\nabla f(w)\|^2 + \sigma^2
\end{align*}
\end{proof}

\section*{Main Proof (Step-by-Step Derivation)}
We derive the expected decrease in the objective function at iteration $t$.
\begin{align*}
&\mathbb{E}_{i_t}[f(w_{t+1})] \\ %[Step 1]
&= \mathbb{E}_{i_t}[f(w_t - \eta \frac{1}{p_{i_t}} \nabla_{i_t} f(w_t) e_{i_t})] \tag{Substitute update rule} \\ %[Step 2]
&\leq \mathbb{E}_{i_t} \left[ f(w_t) - \eta \frac{1}{p_{i_t}} \nabla_{i_t} f(w_t) \cdot \nabla_{i_t} f(w_t) + \frac{L}{2} \eta^2 \frac{1}{p_{i_t}^2} (\nabla_{i_t} f(w_t))^2 \right] \tag{Apply Lemma 1 with $\alpha = \eta / p_{i_t}$} \\ %[Step 3]
&= f(w_t) - \eta \mathbb{E}_{i_t} \left[ \frac{1}{p_{i_t}} \|\nabla_{i_t} f(w_t)\|^2 \right] + \frac{L \eta^2}{2} \mathbb{E}_{i_t} \left[ \frac{1}{p_{i_t}^2} \|\nabla_{i_t} f(w_t)\|^2 \right] \tag{Linearity of Expectation} \\ %[Step 4]
&= f(w_t) - \eta \sum_{i=1}^d p_i \frac{1}{p_i} \|\nabla_i f(w_t)\|^2 + \frac{L \eta^2}{2} \sum_{i=1}^d p_i \frac{1}{p_i^2} \|\nabla_i f(w_t)\|^2 \tag{Expand expectation} \\ %[Step 5]
% CORRECTED: Explicitly show the transition from sum to expectation of the squared norm
&= f(w_t) - \eta \sum_{i=1}^d \|\nabla_i f(w_t)\|^2 + \frac{L \eta^2}{2} \mathbb{E}_{i_t} \left[ \left\| \frac{1}{p_{i_t}} \nabla_{i_t} f(w_t) e_{i_t} \right\|^2 \right] \tag{Cancel $p_i$ terms; re-write as expectation} \\ %[Step 6]
&= f(w_t) - \eta \|\nabla f(w_t)\|^2 + \frac{L \eta^2}{2} \mathbb{E}_{i_t} \left[ \left\| \frac{1}{p_{i_t}} \nabla_{i_t} f(w_t) e_{i_t} \right\|^2 \right] \tag{Sum is full gradient norm} \\ %[Step 7]
% CORRECTED: Apply Lemma 3 as an inequality rather than an equality to properly bound the second moment
&\leq f(w_t) - \eta \|\nabla f(w_t)\|^2 + \frac{L \eta^2}{2} \left( \|\nabla f(w_t)\|^2 + \sigma^2 \right) \tag{Apply Lemma 3} \\ %[Step 8]
&= f(w_t) - \left( \eta - \frac{L \eta^2}{2} \right) \|\nabla f(w_t)\|^2 + \frac{L \eta^2}{2} \sigma^2 \tag{Group gradient terms} \\ %[Step 9]
% CORRECTED: Incorporate the 1/p_i factor into the step size condition to align with the Theorem
&\leq f(w_t) - \frac{\eta}{2} \|\nabla f(w_t)\|^2 + \frac{L \eta^2}{2} \sigma^2 \tag{Assume $\eta \leq \frac{1}{L \max_i 1/p_i}$, so $\eta - L\eta^2/2 \geq \eta/2$} \\ %[Step 10]
\end{align*}
Taking total expectation over all randomness $\mathcal{F}_t = \{i_0, \dots, i_{t-1}\}$:
\begin{align*}
\mathbb{E}[f(w_{t+1})] &\leq \mathbb{E}[f(w_t)] - \frac{\eta}{2} \mathbb{E}[\|\nabla f(w_t)\|^2] + \frac{L \eta^2}{2} \sigma^2 \tag{Total expectation} \\ %[Step 11]
\end{align*}

\section*{Rate Derivation (With Constants)}
% CORRECTED: Fixed the factor of 1/2 inconsistency in the variance term
Rearrange the total expectation inequality to isolate the gradient norm term:
\begin{align*}
\frac{\eta}{2} \mathbb{E}[\|\nabla f(w_t)\|^2] &\leq \mathbb{E}[f(w_t)] - \mathbb{E}[f(w_{t+1})] + \frac{L \eta^2}{2} \sigma^2 \tag{Rearrange} \\ %[Step 12]
\end{align*}
Sum this inequality from $t=0$ to $T-1$:
\begin{align*}
\frac{\eta}{2} \sum_{t=0}^{T-1} \mathbb{E}[\|\nabla f(w_t)\|^2] &\leq \mathbb{E}[f(w_0)] - \mathbb{E}[f(w_T)] + \frac{T L \eta^2}{2} \sigma^2 \tag{Telescoping sum} \\ %[Step 13]
&\leq f(w_0) - f^* + \frac{T L \eta^2}{2} \sigma^2 \tag{Lower bound $f(w_T) \geq f^*$} \\ %[Step 14]
\end{align*}
Divide by $T \eta / 2$:
\begin{align*}
\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E}[\|\nabla f(w_t)\|^2] &\leq \frac{2(f(w_0) - f^*)}{\eta T} + L \eta \sigma^2 \tag{Divide by $T \eta / 2$} \\ %[Step 15]
\end{align*}
To minimize the right hand side with respect to $\eta$, we balance the two terms: $\frac{2(f(w_0)-f^*)}{\eta T} \approx L \eta \sigma^2$. Solving for $\eta$ yields $\eta^* = \sqrt{\frac{2(f(w_0)-f^*)}{L \sigma^2 T}}$. Since we also require $\eta \leq \frac{1}{L \max_i 1/p_i}$ to guarantee descent, we set:
\begin{align*}
\eta = \min \left( \frac{1}{L \max_i \frac{1}{p_i}}, \sqrt{\frac{2(f(w_0)-f^*)}{L \sigma^2 T}} \right)
\end{align*}

\textbf{Case 1:} If $\eta = \frac{1}{L \max_i 1/p_i}$, the bound becomes:
\begin{align*}
\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E}[\|\nabla f(w_t)\|^2] \leq \frac{2L \max_i 1/p_i (f(w_0)-f^*)}{T} + \frac{\sigma^2}{\max_i 1/p_i} = O(1)
\end{align*}
This represents convergence to a neighborhood whose radius depends on the variance.

\textbf{Case 2:} If $\eta = \sqrt{\frac{2(f(w_0)-f^*)}{L \sigma^2 T}}$, substituting gives:
\begin{align*}
\frac{1}{T} \sum_{t=0}^{T-1} \mathbb{E}[\|\nabla f(w_t)\|^2] &\leq \frac{2(f(w_0)-f^*)}{T \sqrt{\frac{2(f(w_0)-f^*)}{L \sigma^2 T}}} + L \sigma^2 \sqrt{\frac{2(f(w_0)-f^*)}{L \sigma^2 T}} \\
&= \frac{\sqrt{2(f(w_0)-f^*) L \sigma^2}}{\sqrt{T}} + \frac{\sqrt{2(f(w_0)-f^*) L \sigma^2}}{\sqrt{T}} \\
&= \frac{2\sqrt{2 L \sigma^2 (f(w_0)-f^*)}}{\sqrt{T}} = O\left(\frac{1}{\sqrt{T}}\right)
\end{align*}

\section*{Special Cases}
\textbf{Uniform Sampling:} If $p_i = 1/d$ for all $i$, then $\max_i 1/p_i = d$. The variance is strictly state-dependent: $\mathbb{E}_i[\|\frac{1}{p_i}\nabla_i f(w)e_i - \nabla f(w)\|^2] = (d-1)\|\nabla f(w)\|^2$. Assuming an absolute bound on gradient norms $\|\nabla f(w)\|^2 \leq G$, we get $\sigma^2 \leq (d-1)G^2$. The step size constraint becomes $\eta \leq \frac{1}{Ld}$, and the rate degrades by a factor of $d$ compared to standard gradient descent.

\textbf{Importance Sampling:} If we choose $p_i = \frac{|\nabla_i f(w)|}{\|\nabla f(w)\|_1}$, then $\frac{1}{p_i} \nabla_i f(w) = \|\nabla f(w)\|_1 \text{sign}(\nabla_i f(w))$. The variance evaluates to:
\begin{align*}
\mathbb{E}_i \left[ \left\| \frac{1}{p_i} \nabla_i f(w) e_i \right\|^2 \right] - \|\nabla f(w)\|^2 = \|\nabla f(w)\|_1^2 - \|\nabla f(w)\|_2^2 \geq 0
\end{align*}
If we use the $L_1$-norm variant of coordinate smoothness, the variance is tightly bounded and often yields better dependency on dimension $d$.
